package com.example.doomeditor;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import java.io.*;
/** Integrated Doom-style sector editor: 2D map, 3D CPU preview, FSM graph. */
public class DoomEditorActivity extends Activity {
 World world;MapView map;RendererView renderer;LinearLayout root,body,tools;TextView status;boolean mode3d=false;int background=0xff202938;
 Button b(String s,Runnable r){Button v=new Button(this);v.setText(s);v.setAllCaps(false);v.setTextSize(12);v.setOnClickListener(x->r.run());return v;}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 void save(){try{FileOutputStream out=openFileOutput("world.json",MODE_PRIVATE);out.write(world.json().toString(2).getBytes("UTF-8"));out.close();toast("Map saved");}catch(Exception e){toast(e.toString());}}
 @Override public void onCreate(Bundle bundle){super.onCreate(bundle);getWindow().getDecorView().setSystemUiVisibility(5894);try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();FileInputStream in=openFileInput("world.json");byte[] b=new byte[4096];int n;while((n=in.read(b))>0)bytes.write(b,0,n);in.close();world=World.parse(bytes.toString("UTF-8"));}catch(Exception ex){world=World.demo();}
 root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(background);setContentView(root);HorizontalScrollView scroll=new HorizontalScrollView(this);LinearLayout tabs=new LinearLayout(this);scroll.addView(tabs);root.addView(scroll);tabs.addView(b("2D Sector Map",()->show(false)));tabs.addView(b("3D Preview",()->show(true)));tabs.addView(b("FSM Graph + Inspector",()->startActivity(new Intent(this,FsmEditorActivity.class))));tabs.addView(b("Save Map",this::save));tabs.addView(b("Sector Settings",this::sectorSettings));body=new LinearLayout(this);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));tools=new LinearLayout(this);tools.setGravity(Gravity.CENTER);root.addView(tools);status=new TextView(this);status.setTextColor(-1);status.setTextSize(12);root.addView(status);map=new MapView(this,world);renderer=new RendererView(this,world);show(false);}
 void show(boolean three){mode3d=three;body.removeAllViews();tools.removeAllViews();if(three){body.addView(renderer,new LinearLayout.LayoutParams(-1,-1));tools.addView(b("◀ Turn",()->renderer.turn(-.15f)));tools.addView(b("▲ Forward",()->renderer.move(.35f,0)));tools.addView(b("▼ Back",()->renderer.move(-.35f,0)));tools.addView(b("Turn ▶",()->renderer.turn(.15f)));tools.addView(b("Strafe ◀",()->renderer.move(0,-.35f)));tools.addView(b("Strafe ▶",()->renderer.move(0,.35f)));status.setText("Software-rendered sector preview • player collision with sector bounds");}else{body.addView(map,new LinearLayout.LayoutParams(-1,-1));tools.addView(b("◀",()->map.step(-1,0)));tools.addView(b("▲",()->map.step(0,-1)));tools.addView(b("▼",()->map.step(0,1)));tools.addView(b("▶",()->map.step(1,0)));tools.addView(b("APPLY",()->map.apply()));tools.addView(b("Close Sector",()->{if(!world.close())toast("Need at least 3 points");map.invalidate();}));tools.addView(b("Undo Point",()->{world.undoPoint();map.invalidate();}));status.setText("D-pad moves grid cursor • APPLY adds vertices • drag canvas to pan");}}
 void sectorSettings(){if(world.sectors.isEmpty()){toast("Draw a sector first");return;}String[] names=new String[world.sectors.size()];for(int i=0;i<names.length;i++)names[i]=world.sectors.get(i).name;new AlertDialog.Builder(this).setTitle("Select sector").setItems(names,(d,idx)->{world.selected=idx;World.Sector s=world.sectors.get(idx);LinearLayout form=new LinearLayout(this);form.setOrientation(1);EditText name=new EditText(this),floor=new EditText(this),ceil=new EditText(this),light=new EditText(this);name.setText(s.name);floor.setText(""+s.floor);ceil.setText(""+s.ceiling);light.setText(""+s.light);form.addView(name);form.addView(floor);form.addView(ceil);form.addView(light);new AlertDialog.Builder(this).setTitle("Name / Floor / Ceiling / Light").setView(form).setPositiveButton("Save",(dd,w)->{try{s.name=name.getText().toString();s.floor=Float.parseFloat(floor.getText().toString());s.ceiling=Float.parseFloat(ceil.getText().toString());s.light=Math.max(0,Math.min(255,Integer.parseInt(light.getText().toString())));map.invalidate();renderer.invalidate();save();}catch(Exception e){toast("Invalid number");}}).setNegativeButton("Cancel",null).show();}).show();}
 @Override protected void onPause(){super.onPause();try{FileOutputStream out=openFileOutput("world.json",MODE_PRIVATE);out.write(world.json().toString().getBytes("UTF-8"));out.close();}catch(Exception ignored){}}
}
